<?php

declare(strict_types=1);

use EventMenu\Core\Auth;
use EventMenu\Core\Database;
use EventMenu\Core\Security;

Auth::requirePermission('events.manage');$tenantId=em_require_tenant();
if($_SERVER['REQUEST_METHOD']==='POST'){
    em_post_csrf();$action=(string)($_POST['action']??'');
    if($action==='event-save'){
        $id=(int)($_POST['id']??0);$name=trim((string)($_POST['name']??''));$starts=(string)($_POST['starts_at']??'');$status=(string)($_POST['status']??'draft');if($name===''||$starts===''||!in_array($status,['draft','published','closed','cancelled'],true))exit('Evento inválido.');$slug=em_slug((string)($_POST['slug']??$name));$ends=(string)($_POST['ends_at']??'');$starts=str_replace('T',' ',$starts);$ends=$ends?str_replace('T',' ',$ends):null;
        if($id){$s=$pdo->prepare('UPDATE events SET name=?,slug=?,description=?,venue=?,address=?,starts_at=?,ends_at=?,status=?,banner_url=? WHERE id=? AND tenant_id=?');$s->execute([$name,$slug,trim((string)($_POST['description']??'')),trim((string)($_POST['venue']??'')),trim((string)($_POST['address']??'')),$starts,$ends,$status,trim((string)($_POST['banner_url']??''))?:null,$id,$tenantId]);}
        else{$slug.='-'.substr(bin2hex(random_bytes(3)),0,5);$s=$pdo->prepare('INSERT INTO events (tenant_id,name,slug,description,venue,address,starts_at,ends_at,status,banner_url) VALUES (?,?,?,?,?,?,?,?,?,?)');$s->execute([$tenantId,$name,$slug,trim((string)($_POST['description']??'')),trim((string)($_POST['venue']??'')),trim((string)($_POST['address']??'')),$starts,$ends,$status,trim((string)($_POST['banner_url']??''))?:null]);$id=(int)$pdo->lastInsertId();}
        Auth::audit('event.saved','event',(string)$id);em_flash('ok','Evento salvo.');em_go('events',['edit'=>$id]);
    }
    if($action==='batch-save'){
        $eventId=(int)($_POST['event_id']??0);$id=(int)($_POST['id']??0);$e=$pdo->prepare('SELECT id FROM events WHERE id=? AND tenant_id=?');$e->execute([$eventId,$tenantId]);if(!$e->fetchColumn())exit('Evento inválido.');$name=trim((string)($_POST['name']??''));$price=(int)round((float)str_replace(',','.',(string)($_POST['price']??'0'))*100);$qty=max(1,(int)($_POST['quantity_total']??1));$start=(string)($_POST['sales_start']??'');$end=(string)($_POST['sales_end']??'');$start=$start?str_replace('T',' ',$start):null;$end=$end?str_replace('T',' ',$end):null;if($name===''||$price<0)exit('Lote inválido.');
        if($id){
            try{Database::transaction(function(PDO $tx)use($id,$eventId,$tenantId,$name,$price,$qty,$start,$end):void{$s=$tx->prepare(Database::portableSql($tx,'SELECT b.quantity_sold,b.quantity_reserved FROM ticket_batches b JOIN events e ON e.id=b.event_id WHERE b.id=? AND b.event_id=? AND e.tenant_id=? FOR UPDATE'));$s->execute([$id,$eventId,$tenantId]);$batch=$s->fetch();if(!$batch)throw new RuntimeException('Lote inválido.');$minimum=(int)$batch['quantity_sold']+(int)$batch['quantity_reserved'];if($qty<$minimum)throw new RuntimeException('Quantidade total não pode ser menor que vendidos + reservados.');$u=$tx->prepare('UPDATE ticket_batches SET name=?,price_cents=?,quantity_total=?,sales_start=?,sales_end=?,active=? WHERE id=? AND event_id=?');$u->execute([$name,$price,$qty,$start,$end,isset($_POST['active'])?1:0,$id,$eventId]);});}catch(Throwable $ex){em_flash('error',$ex->getMessage());em_go('events',['edit'=>$eventId]);}
        }
        else{$s=$pdo->prepare('INSERT INTO ticket_batches (event_id,name,price_cents,quantity_total,sales_start,sales_end,active) VALUES (?,?,?,?,?,?,1)');$s->execute([$eventId,$name,$price,$qty,$start,$end]);$id=(int)$pdo->lastInsertId();}
        Auth::audit('ticket_batch.saved','ticket_batch',(string)$id);em_flash('ok','Lote salvo.');em_go('events',['edit'=>$eventId]);
    }
}
$editId=(int)($_GET['edit']??0);$edit=null;$batches=[];if($editId){$s=$pdo->prepare('SELECT * FROM events WHERE id=? AND tenant_id=?');$s->execute([$editId,$tenantId]);$edit=$s->fetch()?:null;if($edit){$b=$pdo->prepare('SELECT * FROM ticket_batches WHERE event_id=? ORDER BY id');$b->execute([$editId]);$batches=$b->fetchAll();}}
$s=$pdo->prepare('SELECT e.*,(SELECT COALESCE(SUM(quantity_sold),0) FROM ticket_batches b WHERE b.event_id=e.id) sold,(SELECT COALESCE(SUM(quantity_reserved),0) FROM ticket_batches b WHERE b.event_id=e.id) reserved FROM events e WHERE tenant_id=? ORDER BY starts_at DESC');$s->execute([$tenantId]);$events=$s->fetchAll();
em_header('Eventos','events');
?><div class="grid" style="grid-template-columns:minmax(300px,1fr) minmax(0,2fr)"><section class="card"><h2><?= $edit?'Editar evento':'Novo evento' ?></h2><form method="post" class="form-grid"><input type="hidden" name="_csrf" value="<?= em_csrf() ?>"><input type="hidden" name="action" value="event-save"><input type="hidden" name="id" value="<?= (int)($edit['id']??0) ?>"><label class="span-2">Nome<input name="name" required value="<?= Security::e($edit['name']??'') ?>"></label><label class="span-2">Slug público<input name="slug" value="<?= Security::e($edit['slug']??'') ?>" placeholder="gerado automaticamente"></label><label>Início<input type="datetime-local" name="starts_at" required value="<?= $edit?Security::e(date('Y-m-d\TH:i',strtotime($edit['starts_at']))):'' ?>"></label><label>Fim<input type="datetime-local" name="ends_at" value="<?= $edit&&$edit['ends_at']?Security::e(date('Y-m-d\TH:i',strtotime($edit['ends_at']))):'' ?>"></label><label>Status<select name="status"><?php foreach(['draft'=>'Rascunho','published'=>'Publicado','closed'=>'Encerrado','cancelled'=>'Cancelado'] as $v=>$l):?><option value="<?= $v ?>"<?= em_selected($edit['status']??'draft',$v) ?>><?= $l ?></option><?php endforeach;?></select></label><label>Local<input name="venue" value="<?= Security::e($edit['venue']??'') ?>"></label><label class="span-2">Endereço<input name="address" value="<?= Security::e($edit['address']??'') ?>"></label><label class="span-2">Banner (URL)<input type="url" name="banner_url" value="<?= Security::e($edit['banner_url']??'') ?>"></label><label class="span-2">Descrição<textarea name="description"><?= Security::e($edit['description']??'') ?></textarea></label><button class="primary span-2">Salvar evento</button></form><?php if($edit):?><hr style="border-color:var(--line);margin:24px 0"><h2>Novo lote</h2><form method="post" class="form-grid"><input type="hidden" name="_csrf" value="<?= em_csrf() ?>"><input type="hidden" name="action" value="batch-save"><input type="hidden" name="event_id" value="<?= (int)$edit['id'] ?>"><label>Nome<input name="name" placeholder="1º lote" required></label><label>Preço<input name="price" inputmode="decimal" required></label><label>Quantidade<input type="number" name="quantity_total" min="1" required></label><label>Início venda<input type="datetime-local" name="sales_start"></label><label>Fim venda<input type="datetime-local" name="sales_end"></label><button class="secondary span-2">Adicionar lote</button></form><?php endif;?></section><section><div class="card"><div class="section-head"><h2>Eventos</h2><span class="muted"><?= count($events) ?> cadastrados</span></div><div class="table-wrap"><table class="table"><thead><tr><th>Evento</th><th>Data</th><th>Status</th><th>Ingressos</th><th></th></tr></thead><tbody><?php foreach($events as $e):?><tr><td><strong><?= Security::e($e['name']) ?></strong><br><a href="<?= Security::e(app_url('evento.php?evento='.urlencode($e['slug']))) ?>" target="_blank">Página pública</a></td><td><?= Security::e(date('d/m/Y H:i',strtotime($e['starts_at']))) ?></td><td><span class="badge"><?= Security::e($e['status']) ?></span></td><td><?= (int)$e['sold'] ?> pagos · <?= (int)$e['reserved'] ?> reservados</td><td><a class="button secondary" href="<?= Security::e(app_url('?route=events&edit='.(int)$e['id'])) ?>">Editar</a></td></tr><?php endforeach;?></tbody></table></div></div><?php if($edit):?><div class="card" style="margin-top:18px"><div class="section-head"><h2>Lotes de <?= Security::e($edit['name']) ?></h2></div><div class="table-wrap"><table class="table"><thead><tr><th>Lote</th><th>Preço</th><th>Quantidade</th><th>Vendidos</th><th>Reservados</th><th>Disponíveis</th></tr></thead><tbody><?php foreach($batches as $b):$available=max(0,(int)$b['quantity_total']-(int)$b['quantity_sold']-(int)$b['quantity_reserved']);?><tr><td><?= Security::e($b['name']) ?></td><td><?= em_money($b['price_cents']) ?></td><td><?= (int)$b['quantity_total'] ?></td><td><?= (int)$b['quantity_sold'] ?></td><td><?= (int)$b['quantity_reserved'] ?></td><td><strong><?= $available ?></strong></td></tr><?php endforeach;?></tbody></table></div></div><?php endif;?></section></div><?php em_footer();
